CREATE PROCEDURE sp_GetEmployeesByDepartment
    @DepartmentName NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        EmployeeID,
        FirstName + ' ' + LastName AS EmployeeName,
        Salary,
        HireDate
    FROM Employees
    WHERE Department = @DepartmentName
    ORDER BY Salary DESC;
END;

